import{_ as s,o as i,c as n,ag as t}from"./chunks/framework.-Wrcbzkw.js";const u=JSON.parse('{"title":"大模型如何判断何时调用 MCP","description":"","frontmatter":{},"headers":[],"relativePath":"LLM/原理/大模型如何判断何时调用MCP.md","filePath":"LLM/原理/大模型如何判断何时调用MCP.md","lastUpdated":1781074719000}'),e={name:"LLM/原理/大模型如何判断何时调用MCP.md"};function l(p,a,h,o,r,d){return i(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="大模型如何判断何时调用-mcp" tabindex="-1">大模型如何判断何时调用 MCP <a class="header-anchor" href="#大模型如何判断何时调用-mcp" aria-label="Permalink to &quot;大模型如何判断何时调用 MCP&quot;">​</a></h1><p>在支持 MCP（Model Context Protocol）的 Agent 系统中，大模型可以直接回答，也可以调用 MCP Server 提供的工具。模型并不是先理解 MCP 的网络协议再作决定，而是根据当前上下文中提供的工具描述，预测下一步应该生成普通文本还是结构化的工具调用。</p><h2 id="一、mcp-在调用链中的位置" tabindex="-1">一、MCP 在调用链中的位置 <a class="header-anchor" href="#一、mcp-在调用链中的位置" aria-label="Permalink to &quot;一、MCP 在调用链中的位置&quot;">​</a></h2><p>一个典型流程如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户</span></span>
<span class="line"><span>  -&gt; Agent / MCP Client</span></span>
<span class="line"><span>  -&gt; 大语言模型</span></span>
<span class="line"><span>  -&gt; 选择直接回答或请求调用工具</span></span>
<span class="line"><span>  -&gt; MCP Client 执行 MCP 工具</span></span>
<span class="line"><span>  -&gt; 将工具结果返回给模型</span></span>
<span class="line"><span>  -&gt; 模型生成最终回答</span></span></code></pre></div><p>MCP 负责标准化客户端与外部工具、资源和提示模板之间的连接。真正执行工具的是 MCP Client 或宿主应用，不是大模型本身。</p><h2 id="二、模型能看到什么" tabindex="-1">二、模型能看到什么 <a class="header-anchor" href="#二、模型能看到什么" aria-label="Permalink to &quot;二、模型能看到什么&quot;">​</a></h2><p>宿主应用会把可用工具及其说明放入模型上下文。每个工具通常包含：</p><ul><li>工具名称</li><li>功能描述</li><li>参数定义</li><li>参数类型与必填项</li><li>可选的使用约束</li></ul><p>例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_weather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;查询指定城市的实时天气&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;parameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;城市名称&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>当用户问“上海现在天气怎么样”时，模型发现问题需要实时信息，而 <code>get_weather</code> 的描述与任务高度匹配，因此更可能输出工具调用。</p><h2 id="三、模型如何做选择" tabindex="-1">三、模型如何做选择 <a class="header-anchor" href="#三、模型如何做选择" aria-label="Permalink to &quot;三、模型如何做选择&quot;">​</a></h2><p>从模型视角看，直接回答和工具调用都是下一步输出的候选形式。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选 A：生成普通文本答案</span></span>
<span class="line"><span>候选 B：生成 tool_call(get_weather, {&quot;city&quot;: &quot;上海&quot;})</span></span></code></pre></div><p>模型根据系统提示、用户意图、工具描述、对话历史和训练中学到的行为模式，为不同候选分配概率，然后选择更合适的动作。</p><p>模型倾向调用工具的典型情况包括：</p><ol><li><strong>需要实时信息</strong>：天气、股价、新闻和当前系统状态。</li><li><strong>需要私有数据</strong>：企业文档、数据库记录、用户邮件。</li><li><strong>需要执行操作</strong>：发送消息、创建工单、修改文件。</li><li><strong>需要精确计算</strong>：复杂数学、代码执行、数据分析。</li><li><strong>系统明确要求</strong>：规定某类问题必须通过指定工具处理。</li></ol><p>模型倾向直接回答的情况包括：</p><ul><li>普通知识解释</li><li>不依赖实时信息的概念问题</li><li>仅需改写、总结或翻译当前上下文</li><li>工具无法帮助完成任务</li></ul><h2 id="四、为什么有时会选错" tabindex="-1">四、为什么有时会选错 <a class="header-anchor" href="#四、为什么有时会选错" aria-label="Permalink to &quot;四、为什么有时会选错&quot;">​</a></h2><p>工具选择不是硬编码判断，而是概率决策，因此可能出现错误。</p><h3 id="应调用却直接回答" tabindex="-1">应调用却直接回答 <a class="header-anchor" href="#应调用却直接回答" aria-label="Permalink to &quot;应调用却直接回答&quot;">​</a></h3><p>原因可能是工具描述不清晰、模型认为自身知识足够，或系统提示没有强调实时性与准确性要求。</p><h3 id="不需要却调用工具" tabindex="-1">不需要却调用工具 <a class="header-anchor" href="#不需要却调用工具" aria-label="Permalink to &quot;不需要却调用工具&quot;">​</a></h3><p>原因可能是工具描述过于宽泛，或者系统提示过度鼓励调用工具。</p><h3 id="选择了错误工具" tabindex="-1">选择了错误工具 <a class="header-anchor" href="#选择了错误工具" aria-label="Permalink to &quot;选择了错误工具&quot;">​</a></h3><p>当多个工具名称和描述相似时，模型可能无法区分各自边界。</p><h3 id="参数填写错误" tabindex="-1">参数填写错误 <a class="header-anchor" href="#参数填写错误" aria-label="Permalink to &quot;参数填写错误&quot;">​</a></h3><p>工具参数过多、命名模糊或缺少示例时，模型更容易遗漏或误填参数。</p><h2 id="五、如何提高工具选择准确率" tabindex="-1">五、如何提高工具选择准确率 <a class="header-anchor" href="#五、如何提高工具选择准确率" aria-label="Permalink to &quot;五、如何提高工具选择准确率&quot;">​</a></h2><h3 id="_1-编写清晰的工具描述" tabindex="-1">1. 编写清晰的工具描述 <a class="header-anchor" href="#_1-编写清晰的工具描述" aria-label="Permalink to &quot;1. 编写清晰的工具描述&quot;">​</a></h3><p>工具描述应说明它做什么、何时使用，以及何时不应使用。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查询实时天气。仅在用户询问当前或未来天气时使用；</span></span>
<span class="line"><span>不要用于解释气候、季节等一般知识。</span></span></code></pre></div><h3 id="_2-让工具职责单一" tabindex="-1">2. 让工具职责单一 <a class="header-anchor" href="#_2-让工具职责单一" aria-label="Permalink to &quot;2. 让工具职责单一&quot;">​</a></h3><p>一个工具只处理一种明确任务，比一个接收大量可选参数的万能工具更容易被正确选择。</p><h3 id="_3-使用明确的参数定义" tabindex="-1">3. 使用明确的参数定义 <a class="header-anchor" href="#_3-使用明确的参数定义" aria-label="Permalink to &quot;3. 使用明确的参数定义&quot;">​</a></h3><p>参数名称、类型、枚举值和描述越清晰，模型越容易生成合法调用。</p><h3 id="_4-在系统提示中制定规则" tabindex="-1">4. 在系统提示中制定规则 <a class="header-anchor" href="#_4-在系统提示中制定规则" aria-label="Permalink to &quot;4. 在系统提示中制定规则&quot;">​</a></h3><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>涉及实时数据时必须调用工具，不得凭记忆回答。</span></span>
<span class="line"><span>执行写操作前必须先获得用户确认。</span></span></code></pre></div><h3 id="_5-在应用层增加控制" tabindex="-1">5. 在应用层增加控制 <a class="header-anchor" href="#_5-在应用层增加控制" aria-label="Permalink to &quot;5. 在应用层增加控制&quot;">​</a></h3><p>高风险操作不能完全依赖模型判断。宿主应用应增加权限检查、参数校验、用户确认、超时、重试和审计日志。</p><h3 id="_6-建立工具调用评测集" tabindex="-1">6. 建立工具调用评测集 <a class="header-anchor" href="#_6-建立工具调用评测集" aria-label="Permalink to &quot;6. 建立工具调用评测集&quot;">​</a></h3><p>为“应调用”“不应调用”“应该调用哪个工具”等场景建立测试用例，持续评估模型的选择准确率。</p><h2 id="六、mcp-与-function-calling-的关系" tabindex="-1">六、MCP 与 Function Calling 的关系 <a class="header-anchor" href="#六、mcp-与-function-calling-的关系" aria-label="Permalink to &quot;六、MCP 与 Function Calling 的关系&quot;">​</a></h2><p>Function Calling 是模型输出结构化工具调用的一种能力；MCP 是宿主应用发现、连接和调用外部能力的一种标准协议。</p><p>可以简单理解为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Function Calling：模型如何表达“我要调用这个工具”</span></span>
<span class="line"><span>MCP：应用如何发现工具、执行工具并返回结果</span></span></code></pre></div><p>两者经常配合使用，但职责不同。</p><h2 id="七、一个完整示例" tabindex="-1">七、一个完整示例 <a class="header-anchor" href="#七、一个完整示例" aria-label="Permalink to &quot;七、一个完整示例&quot;">​</a></h2><p>用户提出问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我查看今天未读的工作邮件，并总结最紧急的三封。</span></span></code></pre></div><p>模型的决策过程可以概括为：</p><ol><li>当前上下文中没有用户的实时邮件数据。</li><li>可用工具中存在邮件搜索工具。</li><li>该任务只需读取数据，不需要发送或删除邮件。</li><li>模型生成邮件搜索工具调用。</li><li>MCP Client 执行调用并返回邮件列表。</li><li>模型根据结果判断紧急程度并生成总结。</li></ol><p>如果用户只是问“如何判断一封邮件是否紧急”，模型通常可以直接回答，因为该问题不依赖用户的真实邮箱数据。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>大模型知道何时调用 MCP 工具，主要依靠：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户意图</span></span>
<span class="line"><span>+ 系统提示中的规则</span></span>
<span class="line"><span>+ 工具名称、描述和参数</span></span>
<span class="line"><span>+ 对话上下文</span></span>
<span class="line"><span>+ 工具调用训练形成的行为模式</span></span></code></pre></div><p>模型负责提出调用请求，MCP Client 负责实际执行。要构建可靠的 Agent，不能只依赖模型的概率判断，还需要清晰的工具设计和应用层安全控制。</p>`,60)])])}const k=s(e,[["render",l]]);export{u as __pageData,k as default};
